// n8n Code node - Run Once for All Items
const results = [];

for (const item of $input.all()) {
  const data = item.json;
  const sheetUrl = data.sheetUrl || '';

  // Extract gid from the URL (matches ?gid=0, &gid=123, #gid=0, etc.)
  const gidMatch = sheetUrl.match(/[?&#]gid=(\d+)/);
  const gid = gidMatch ? gidMatch[1] : null;

  results.push({
    json: {
      action_type: data.actionType || null,
      sheet_url: sheetUrl,
      gid: gid,
      filter_by_job_role_inclusion: data.filterByJobRoleInclusion

    },
  });
}

return results;

// Get all items from the previous node
const previousItems = $input.all();

return $input.all();

// 1. Data from the previous-previous node
const exclusionData = $('GET: AEML - PREVIOUS EXCLUSIONS').all().map(item => item.json);

// 2. Data from the immediately previous node
const previousData = $input.all().map(item => item.json);

const excluders = ['Tom', 'Ines', 'Luke', 'Rica', 'Rohan'];

// Normalize names so casing/spacing differences don't break the match
const normalize = (name) => (name || '').trim().toLowerCase();

const results = previousData.map(row => {
  const match = exclusionData.find(ex => normalize(ex.name) === normalize(row.name));

  const matchName = !!match;

  const output = {
    row_number: row.row_number,
    name: row.name,
    match_name: matchName
  };

  // Add one field per excluder, only set when there's an "X"
  excluders.forEach(person => {
    const val = match ? match[person] : null;
    output[person] = (val && val.toString().trim().toUpperCase() === 'X') ? 'X' : null;
  });

  return { json: output };
});

return results;

// Exclusion list of job roles comes from the immediately previous node
const exclusionItems = $input.all();

// Pull the original user sheet data from the "RETRIEVE USER SHEET PROVIDED" node
const userSheetItems = $('RETRIEVE USER SHEET PROVIDED V1').all();

// Build a normalized array of exclusion job roles (trimmed, lowercased, deduped)
const exclusionRoles = [
  ...new Set(
    exclusionItems
      .map(item => (item.json.job_role || '').trim().toLowerCase())
      .filter(role => role !== '')
  )
];

// Walk through the user sheet and flag partial matches
return userSheetItems.map(item => {
  const jobRole = (item.json.job_role || '').trim().toLowerCase();

  let isMatch = false;
  if (jobRole !== '') {
    isMatch = exclusionRoles.some(exclRole => jobRole.includes(exclRole));
  }

  return {
    json: {
      ...item.json,
      job_role_exclusion_match: isMatch
    }
  };
});

// Exclusion list of job roles comes from the immediately previous node
const exclusionItems = $input.all();

// Pull the original user sheet data from the "FILTERED: RETRIEVE USER SHEET PROVIDED" node
const userSheetItems = $('RETRIEVE USER SHEET PROVIDED V1').all();

// Pull the job role inclusion master list
const inclusionItems = $('FILTERED: GET: AEML - JOB ROLE INCLUSION').all();

// Build a normalized array of exclusion job roles (trimmed, lowercased, deduped)
const exclusionRoles = [
  ...new Set(
    exclusionItems
      .map(item => (item.json.job_role || '').trim().toLowerCase())
      .filter(role => role !== '')
  )
];

// Build a normalized array of inclusion job roles (trimmed, lowercased, deduped)
const inclusionRoles = [
  ...new Set(
    inclusionItems
      .map(item => (item.json.job_role || '').trim().toLowerCase())
      .filter(role => role !== '')
  )
];

// Walk through the user sheet and flag partial matches
return userSheetItems.map(item => {
  const jobRole = (item.json.job_role || '').trim().toLowerCase();

  let isMatch = false;
  if (jobRole !== '') {
    isMatch = exclusionRoles.some(exclRole => jobRole.includes(exclRole));
  }

  // Inclusion master list always overrides exclusion, even on a match
  let isIncluded = false;
  if (jobRole !== '') {
    isIncluded = inclusionRoles.some(inclRole => jobRole.includes(inclRole));
  }

  if (isIncluded) {
    isMatch = false;
  }

  return {
    json: {
      ...item.json,
      job_role_exclusion_match: isMatch
    }
  };
});

// Pull all items from both upstream nodes (names must match exactly)
const jobRole   = $('FILTER ON: FINAL JOB ROLE EXCL').all().map(i => i.json);
const prevEvent = $('FINAL PREVIOUS EVENT EXCLUSION').all().map(i => i.json);

// Merge by row_number (full outer join: keeps rows that exist in either node)
const merged = new Map();
for (const row of [...prevEvent, ...jobRole]) {
  const key = row.row_number;
  merged.set(key, { ...(merged.get(key) || {}), ...row });
}

return [...merged.values()]
  .sort((a, b) => a.row_number - b.row_number)
  .map(row => ({ json: row }));

